67	// The authenticated user is read per upgrade, so one test can reconnect as someone else.
68	const startEngine = async (
69	  store: SessionStore,
70	  resume?: SessionResumeOptions,
71	  orchestrator: ChatOrchestrator = answeringOrchestrator
72	) => {
73	  const auth = {userId: 'u1'};
74	  const connects: Array<{sessionId: string; resumed: boolean}> = [];
75	  const disconnected: string[] = [];
76	  const hal = createServer({
77	    app: (() => undefined) as unknown as Express,
78	    wsAuth: async () => ({id: auth.userId}),
79	    sessionStore: store,
80	    orchestrator,
81	    resume,
82	    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
83	    onDisconnect: sessionId => void disconnected.push(sessionId),
84	  });
85	  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
86	  const firstServerClose = new Promise<void>(resolve => {
87	    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
88	  });
89	  await hal.start(0);
90	  servers.push(hal);
91	  const {port} = hal.server.address() as AddressInfo;
92	  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
93	};
94	
95	const open = (url: string, token = 't'): WebSocket => {
96	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
97	  clients.push(client);
98	  return client;
99	};
100	
101	// One question answered and the socket closed, returning the id the connected frame announced.
102	const firstTurn = async (base: string): Promise<string> => {
103	  const client = open(base);
104	  let sessionId = '';
105	  await new Promise<void>(resolve => {
106	    client.on('message', raw => {
107	      const frame = JSON.parse(String(raw)) as Frame;
108	      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
109	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
110	      if (frame.type === 'stream_end') resolve();
111	    });
112	  });
113	  client.close();
114	  await once(client, 'close');
115	  return sessionId;
116	};
117	
118	// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
119	const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
120	  const client = open(url, token);
121	  const frames: Frame[] = [];
122	  await new Promise<void>(resolve => {
123	    client.on('message', raw => {
124	      const frame = JSON.parse(String(raw)) as Frame;
125	      frames.push(frame);
126	      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
127	      if (frame.type === 'pong') resolve();
128	    });
129	  });
130	  return frames;
131	};
132	
133	const upserts = (frames: Frame[]) =>
134	  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));
135	
136	const shapeOf = (frames: Frame[]) => ({
137	  keys: Object.keys(frames[0]).sort(),
138	  resumed: frames[0].resumed,
139	  resumeFailure: frames[0].resumeFailure,
140	  types: frames.map(frame => frame.type),
141	});
142	
143	const deferredRelease = () => {
144	  let release = (): void => undefined;
145	  const until = new Promise<void>(resolve => {
146	    release = resolve;
147	  });
148	  return {until, release: () => release()};
149	};
150	
151	// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
152	const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
153	  const store = new InMemorySessionStore();
154	  for (const [sessionId, userId, sentAt] of conversations) {
155	    const {entries} = store.create(sessionId, userId);
156	    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
157	  }
158	  return store;
159	};
160	
161	describe('resuming a conversation on reconnect', () => {
162	  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
163	    const {base} = await startEngine(new InMemorySessionStore());
164	    const first = await firstTurn(base);
165	
166	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
167	
168	    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
169	      newId: true,
170	      shape: {
171	        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
172	        resumed: undefined,
173	        types: ['connected', 'pong'],
174	      },
175	    });
176	  });
177	
178	  it('with resume on, answers the owner reconnecting with resumed true, entryCount 2 and both stored entries', async () => {
179	    const store = new InMemorySessionStore();
180	    const {base} = await startEngine(store, RESUME_ON);
181	    const first = await firstTurn(base);
182	
183	    const frames = await connectAndSettle(`${base}?sessionId=${first}`);
184	
185	    const stored = JSON.parse(JSON.stringify((await store.get(first))?.entries)) as SessionEntry[];
186	    expect({connected: frames[0], replay: upserts(frames)}).toMatchObject({
187	      connected: {type: 'connected', sessionId: first, resumed: true, entryCount: 2},
188	      replay: [
189	        {index: 0, entry: stored[0]},
190	        {index: 1, entry: stored[1]},
191	      ],
192	    });
193	  });
194	
195	  it('answers another user naming the id exactly as it answers an id that was never issued', async () => {
196	    const {auth, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
197	    const first = await firstTurn(base);
198	    auth.userId = 'u2';
199	
200	    const otherUser = await connectAndSettle(`${base}?sessionId=${first}`);
201	    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
202	
203	    expect({fresh: otherUser[0].sessionId !== first, otherUser: shapeOf(otherUser)}).toEqual({
204	      fresh: true,
205	      otherUser: shapeOf(neverIssued),
206	    });
207	  });
208	
209	  it('answers a never-issued id with resumed false, resumeFailure unknown, and no replay or error', async () => {
210	    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
211	
212	    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
213	
214	    expect(shapeOf(frames)).toEqual({
215	      keys: ['examplePrompts', 'message', 'resumeFailure', 'resumed', 'sessionId', 'type'],
216	      resumed: false,
217	      resumeFailure: 'unknown',
218	      types: ['connected', 'pong'],
219	    });
220	  });
221	
222	  it('never adopts a requested id as a key: one session, under the id the server minted', async () => {
223	    const store = new InMemorySessionStore();
